import torch
import pandas as pd
import re
from transformers import AutoTokenizer, AutoModelForCausalLM
from tqdm import tqdm
from config import Config

def extract_first_number(text):
    """Extracts the FIRST number generated by the model (the final answer)."""
    # Find all sequences of digits in the text
    numbers = re.findall(r'\d+', text)
    if numbers:
        return numbers[0] # Return the very first number
    return "INVALID"

def evaluate_baseline_accuracy(model, tokenizer, config, datapath="test.csv"):
    """Evaluates the baseline accuracy of the model on the test dataset."""
    model.eval()

    total_correct = 0
    total_count = 0

    # 1. Load Data
    test_data = pd.read_csv(datapath)
    

    for idx, row in tqdm(test_data.iterrows(), total=len(test_data), desc="Evaluating"):
        base_num1 = row["Base Num1"]
        base_num2 = row["Base Num2"]
        expected_output = str(row["Expected Base Output"]).strip()
        
        # 2. Construct the Prompt
        prompt_template = (
            "Answer the following addition problem with just the number.\n\n"
            "Question: What is 12 + 15?\n"
            "Answer: 27\n\n"
            "Question: What is 23 + 34?\n"
            "Answer: 57\n\n"
            f"Question: What is {base_num1} + {base_num2}?\n"
            "Answer:"
        )

        # 3. Tokenize
        inputs = tokenizer(prompt_template, return_tensors="pt").to(config.device)

        # 4. Generate
        with torch.no_grad():
            outputs = model.generate(
                **inputs, 
                max_new_tokens=10,
                do_sample=False,
                pad_token_id=tokenizer.eos_token_id,
                eos_token_id=tokenizer.encode("\n")[0]
            )

        # 5. Decode ONLY the newly generated tokens
        generated_ids = outputs[0][inputs["input_ids"].shape[1]:]
        generated_text = tokenizer.decode(generated_ids, skip_special_tokens=True).strip()

        # 6. Parse the prediction
        predicted_answer = extract_first_number(generated_text)

        # 7. Check Accuracy
        if predicted_answer == expected_output:
            total_correct += 1
        total_count += 1

        # Print the first 5 examples to verify it's working
        if idx < 5:
            print(f"\n[Example {idx+1}]")
            print(f"Prompt: What is {base_num1} + {base_num2}?")
            print(f"Model Generated: '{generated_text}'")
            print(f"Parsed: {predicted_answer} | Expected: {expected_output} | Match: {predicted_answer == expected_output}")

    accuracy = total_correct / total_count if total_count > 0 else 0
    print(f"\nFinal Baseline Accuracy: {accuracy:.2%}")

    return accuracy

if __name__ == "__main__":
    config = Config()
    torch.manual_seed(config.seed)
    
    model_list = config.model_name

    for model_name in model_list:
        print(f"\n{'='*60}")
        print(f"Evaluating Baseline Accuracy for Model: {model_name}")
        print(f"{'='*60}")

        # Load Tokenizer and Model
        tokenizer = AutoTokenizer.from_pretrained(model_name)
        if tokenizer.pad_token is None:
            tokenizer.pad_token = tokenizer.eos_token

        model = AutoModelForCausalLM.from_pretrained(
            model_name, torch_dtype=config.dtype, device_map="auto"
        )
        model.eval()

        # Evaluate Baseline Accuracy
        acc = evaluate_baseline_accuracy(model, tokenizer, config, datapath="test.csv")
        
        # Clean up memory for the next model
        del model
        torch.cuda.empty_cache()